    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "To be eligible for inclusion in the present review, studies needed to meet the following criteria: (i) were children or adolescents aged 5-19 years, all countries and ethnic backgrounds; (ii) had a MetS outcome; (iii) had an adherence to the MedDiet assessed by a validated questionnaire; and (iv) had a longitudinal and cross-­ sectional study design.",
      "reason": "Population (age 5-19, all countries), outcome (MetS), exposure (validated MedDiet questionnaire), and eligible study designs are explicitly specified."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_20",
      "quote": "we restricted our inclusion criteria to studies published in English",
      "reason": "Language restriction is mentioned, but only in the Discussion as a limitation; no dissemination year range or publication status criteria are reported in the Methods/eligibility criteria."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No distinction is made between excluding studies because outcomes were not measured versus outcomes not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_17",
      "quote": "Children and adolescents with low adherence to the MedDiet had greater odds of developing MetS compared to those with medium to high adherence.",
      "reason": "Comparison groups for the synthesis (low vs medium-to-high MedDiet adherence) are implied by the results, but grouping rules for the synthesis are not explicitly specified in the Methods or linked to review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "However, to narrow the scope of the meta-­ analysis, only studies that associated the MedDiet with the outcome of MetS were included.",
      "reason": "A rationale is given for restricting inclusion to studies associating MedDiet with MetS (to narrow the meta-analysis scope)."
    }
  ],
  "confidence": 85
}

